= SootopolisCity_EventScript_Wallace
lock
faceplayer
goto_if_eq VAR_SOOTOPOLIS_CITY_STATE 4 SootopolisCity_EventScript_GoToSkyPillar
goto_if_set FLAG_RECEIVED_HM_WATERFALL SootopolisCity_EventScript_GoToGym
goto_if_set FLAG_SOOTOPOLIS_ARCHIE_MAXIE_LEAVE SootopolisCity_EventScript_GiveWaterfall
msgbox	WALLACE: PLAYER…Ich glaube nicht, dass die Anführer von TEAM MAGMA und AQUA Böses im Sinn hatten.Es würde nicht schaden, zu hören, was sie selbst dazu zu sagen haben.
release
end
= SootopolisCity_EventScript_GiveWaterfall
msgbox	WALLACE: PLAYER… Meine Augen haben mich nicht getäuscht.Dank deiner Hilfe wurde SOOTOPOLIS… nein, ganz HOENN gerettet.Im Namen aller Menschen danke ich dir.Das hier ist ein Geschenk von mir. Bitte nimm es an.
giveitem ITEM_HM_WATERFALL
setflag FLAG_RECEIVED_HM_WATERFALL
msgbox	Diese VERSTECKTE MASCHINE enthält WASSERFALL.Wenn du den REGEN-ORDEN besitzt, kann ein POKéMON, das diese VM-Attacke erlernt hat, sich Wasserfälle hinaufkämpfen.Und wo bekommt man den REGEN-ORDEN her? Das weißt du doch, oder?Genau! Du musst den SOOTOPOLIS-ARENALEITER besiegen.Wenn du bereit bist, geh durch diese Tür.
closemessage
call_if_eq VAR_FACING DIR_NORTH SootopolisCity_EventScript_WallaceMoveFromGym
call_if_eq VAR_FACING DIR_EAST SootopolisCity_EventScript_WallaceMoveFromGym
call_if_eq VAR_FACING DIR_WEST SootopolisCity_EventScript_WallaceMoveFromGymWest
release
end
= SootopolisCity_EventScript_WallaceMoveFromGymWest
applymovement LOCALID_SOOTOPOLIS_WALLACE SootopolisCity_Movement_WallaceMoveFromGymWest
waitmovement 0
copyobjectxytoperm LOCALID_SOOTOPOLIS_WALLACE
setvar VAR_SOOTOPOLIS_WALLACE_STATE 2
return
= SootopolisCity_EventScript_WallaceMoveFromGym
applymovement LOCALID_SOOTOPOLIS_WALLACE SootopolisCity_Movement_WallaceMoveFromGym
waitmovement 0
copyobjectxytoperm LOCALID_SOOTOPOLIS_WALLACE
setvar VAR_SOOTOPOLIS_WALLACE_STATE 1
return
= SootopolisCity_EventScript_GoToGym
msgbox	WALLACE: Ich bin mir sicher, dass dich der atemberaubend elegante Kampfstil meines Lehrmeisters verzaubern wird.
release
end
= SootopolisCity_EventScript_GoToSkyPillar
msgbox	WALLACE: Oh? PLAYER?Hast du den HIMMELSPFEILER noch nicht erklommen?Ich bin mir sicher, dass du es bis an die Spitze des HIMMELSPFEILERS schaffen kannst…
release
end
= SootopolisCity_EventScript_Archie
lockall
goto_if_eq VAR_SOOTOPOLIS_CITY_STATE 5 SootopolisCity_EventScript_ArchieRayquaza
msgbox	ARCHIE: KYOGRE! Was ist los?! Sieh hierher! Das ist die ROTE ORB! Beruhige dich! KYOGRE!… … … … … … … … … … … …Es nützt nichts! Es reagiert überhaupt nicht!
closemessage
releaseall
end
= SootopolisCity_EventScript_ArchieRayquaza
msgbox	ARCHIE: KYOGRE und GROUDON sind beide fortgeflogen, wer weiß wohin.Das Wetter in HOENN ist wieder normal geworden…Haha… Hahaha…Vielleicht war das, was wir vorhatten, für POKéMON etwas Kleines, ja sogar Bedeutungsloses…
setflag FLAG_MET_ARCHIE_SOOTOPOLIS
goto_if_set FLAG_MET_MAXIE_SOOTOPOLIS SootopolisCity_EventScript_MaxieArchieLeave
releaseall
end
= SootopolisCity_EventScript_MaxieArchieLeave
setflag FLAG_HIDE_SOOTOPOLIS_CITY_MAXIE
setflag FLAG_HIDE_SOOTOPOLIS_CITY_ARCHIE
setflag FLAG_SOOTOPOLIS_ARCHIE_MAXIE_LEAVE
clearflag FLAG_HIDE_MT_PYRE_SUMMIT_MAXIE
clearflag FLAG_HIDE_MT_PYRE_SUMMIT_ARCHIE
setvar VAR_MT_PYRE_STATE 2
warpsilent SootopolisCity 31 34
waitstate
releaseall
end
@ Unused
goto SootopolisCity_Movement_Levitate
= SootopolisCity_Movement_Levitate
levitate
step_end
@ Unused
goto SootopolisCity_Movement_DestroyTask
= SootopolisCity_Movement_DestroyTask
destroy_extra_task
step_end
= SootopolisCity_EventScript_Maxie
lockall
goto_if_eq VAR_SOOTOPOLIS_CITY_STATE 5 SootopolisCity_EventScript_MaxieRayquaza
msgbox	MAXIE: G… GROUDON… Bitte! Hör auf damit!Ich kenne jetzt das Ausmaß deiner Kraft!Wenn du so weitermachst, wird nicht nur SOOTOPOLIS, sondern ganz HOENN restlos zerstört!
closemessage
releaseall
end
= SootopolisCity_EventScript_MaxieRayquaza
msgbox	MAXIE: Die uralten POKéMON waren also nicht nur GROUDON und KYOGRE…Nach all unseren vergeblichen Plänen und verzweifelten Bemühungen bringt eine einzige, simple Handlung dieses einen POKéMON alles wieder in Ordnung, als wäre nichts geschehen…Fu… Fuhahaha…
setflag FLAG_MET_MAXIE_SOOTOPOLIS
goto_if_set FLAG_MET_ARCHIE_SOOTOPOLIS SootopolisCity_EventScript_MaxieArchieLeave
releaseall
end
= SootopolisCity_EventScript_Boy2
lockall
applymovement LOCALID_SOOTOPOLIS_BOY_2 Common_Movement_FacePlayer
waitmovement 0
goto_if_eq VAR_SOOTOPOLIS_CITY_STATE 5 SootopolisCity_EventScript_Boy2Rayquaza
msgbox	Ich habe irgendwie das Gefühl, dass die beiden POKéMON gar nicht wütend sind.Ich glaube… Sie können wahrscheinlich einfach ihre eigene Kraft nicht kontrollieren…
closemessage
applymovement LOCALID_SOOTOPOLIS_BOY_2 Common_Movement_FaceOriginalDirection
waitmovement 0
releaseall
end
= SootopolisCity_EventScript_Boy2Rayquaza
msgbox	Das fliegende POKéMON kam vom Himmel herab und stoppte die tobenden POKéMON…
closemessage
releaseall
end
= SootopolisCity_EventScript_BlackBelt
lockall
goto_if_eq VAR_SOOTOPOLIS_CITY_STATE 5 SootopolisCity_EventScript_BlackBeltRayquaza
msgbox	Gib alles, rotes POKéMON! Gib nicht auf, blaues POKéMON!
closemessage
applymovement LOCALID_SOOTOPOLIS_BLACK_BELT Common_Movement_FacePlayer
waitmovement 0
msgbox	… … … … … …Hi, kennst du die Namen der POKéMON, die dort drüben kämpfen?
closemessage
applymovement LOCALID_SOOTOPOLIS_BLACK_BELT Common_Movement_FaceOriginalDirection
waitmovement 0
releaseall
end
= SootopolisCity_EventScript_BlackBeltRayquaza
applymovement LOCALID_SOOTOPOLIS_BLACK_BELT Common_Movement_FacePlayer
waitmovement 0
msgbox	Ich habe mich gefragt, ob wohl das rote oder das blaue gewinnt, aber oh nein, das grüne entscheidet die Sache!Was für eine gewaltige Wendung!
releaseall
end
= SootopolisCity_EventScript_Girl
lockall
applymovement LOCALID_SOOTOPOLIS_GIRL Common_Movement_FacePlayer
waitmovement 0
goto_if_eq VAR_SOOTOPOLIS_CITY_STATE 5 SootopolisCity_EventScript_GirlRayquaza
msgbox	Oh nein! SOOTOPOLIS CITY wird zerstört!
closemessage
applymovement LOCALID_SOOTOPOLIS_GIRL Common_Movement_FaceOriginalDirection
waitmovement 0
releaseall
end
= SootopolisCity_EventScript_GirlRayquaza
msgbox	SOOTOPOLIS CITY wurde nicht zerstört!
closemessage
releaseall
end
= SootopolisCity_EventScript_Maniac
lockall
applymovement LOCALID_SOOTOPOLIS_MANIAC Common_Movement_FacePlayer
waitmovement 0
goto_if_eq VAR_SOOTOPOLIS_CITY_STATE 5 SootopolisCity_EventScript_ManiacRayquaza
msgbox	Es gibt eine uralte Legende, die besagt, dass Land und Meer durch einen gewaltigen Kampf zwischen POKéMON geformt wurden.Und genau das sehe ich hier mit meinen eigenen Augen!Wow! Ich hätte nie gedacht, so etwas Gewaltiges mitzuerleben!
closemessage
applymovement LOCALID_SOOTOPOLIS_MANIAC Common_Movement_FaceOriginalDirection
waitmovement 0
releaseall
end
= SootopolisCity_EventScript_ManiacRayquaza
msgbox	Es gibt eine uralte Legende, die besagt, dass Land und Meer durch einen gewaltigen Kampf zwischen POKéMON geformt wurden.Und genau das habe ich mit meinen eigenen Augen gesehen!Wow! Ich hätte nie gedacht, so etwas Gewaltiges mitzuerleben!
releaseall
end
= SootopolisCity_EventScript_Woman1
lock
faceplayer
goto_if_ge VAR_SOOTOPOLIS_CITY_STATE 6 SootopolisCity_EventScript_Woman1PostLegendaries
goto_if_eq VAR_SOOTOPOLIS_CITY_STATE 5 SootopolisCity_EventScript_Woman1Rayquaza
goto_if_ge VAR_SOOTOPOLIS_CITY_STATE 2 SootopolisCity_EventScript_Woman1Legendaries
msgbox	SOOTOPOLIS entstand als Stadt im Krater eines Vulkans.Wenn du zum Himmel hinaufschaust, siehst du auch den Kraterrand. Man sieht also den Himmel nur als Kreis.Aber gerade das macht den Himmel über SOOTOPOLIS so wunderschön.
release
end
= SootopolisCity_EventScript_Woman1Legendaries
msgbox	Wenn zwei so riesige POKéMON derart wild kämpfen, können wir kaum etwas tun.
closemessage
applymovement LOCALID_SOOTOPOLIS_WOMAN_1 Common_Movement_FaceOriginalDirection
waitmovement 0
release
end
= SootopolisCity_EventScript_Woman1Rayquaza
msgbox	Als das dritte POKéMON herabflog, befürchtete ich das Schlimmste.
release
end
= SootopolisCity_EventScript_Woman1PostLegendaries
msgbox	Ein nächtlicher Himmel, eingerahmt vom Krater eines Vulkans…Und in diesem Ring flackern und funkeln Sterne, als wären sie lebendig… Das ist mein liebster Anblick.
release
end
= SootopolisCity_EventScript_Steven
lockall
applymovement LOCALID_SOOTOPOLIS_STEVEN Common_Movement_FacePlayer
waitmovement 0
call_if_unset FLAG_STEVEN_GUIDES_TO_CAVE_OF_ORIGIN SootopolisCity_EventScript_StevenLeadPlayerCaveOfOrigin
goto_if_eq VAR_SOOTOPOLIS_CITY_STATE 2 SootopolisCity_EventScript_StevenHelpWallace
goto_if_eq VAR_SOOTOPOLIS_CITY_STATE 3 SootopolisCity_EventScript_StevenHelpedWallace
goto_if_eq VAR_SOOTOPOLIS_CITY_STATE 4 SootopolisCity_EventScript_StevenHelpedWallace
goto_if_set FLAG_SOOTOPOLIS_ARCHIE_MAXIE_LEAVE SootopolisCity_EventScript_StevenMaxieArchieLeft
msgbox	STEVEN: Das also ist RAYQUAZA…Unglaublich, wie die beiden tobenden POKéMON aus Angst vor ihm fliehen…
releaseall
end
= SootopolisCity_EventScript_StevenMaxieArchieLeft
msgbox	STEVEN: Es sieht so aus, als wären MAXIE und ARCHIE beide irgendwohin verschwunden.Vielleicht sind sie zum BEBEN-BERG gegangen, um die ORBS zurückzubringen…
releaseall
end
= SootopolisCity_EventScript_StevenHelpedWallace
msgbox	STEVEN: Der HIMMELSPFEILER…Ich war noch nie dort. Ich frage mich, wo er wohl sein könnte?
releaseall
end
= SootopolisCity_EventScript_StevenHelpWallace
msgbox	STEVEN: Ich denke, du hast das Zeug, ihm zu helfen…
releaseall
end
= SootopolisCity_EventScript_StevenLeadPlayerCaveOfOrigin
msgbox	STEVEN: Diese kämpfenden POKéMON… GROUDON… Und KYOGRE…Die beiden uralten POKéMON wurden aus einem langen Schlaf geweckt…Und jetzt zerschmettern sie einander mit ihrer unkontrollierbaren Energie……PLAYER.Dass du jetzt hier bist, nehme ich als Zeichen, dass du bereit bist, dich in diese Krise einzumischen.Nun, dann gibt es jemanden, den ich dich gerne treffen lassen würde.Komm bitte mit mir.
closemessage
call_if_eq VAR_FACING DIR_WEST SootopolisCity_EventScript_StartWalkToCaveOfOriginWest
call_if_eq VAR_FACING DIR_NORTH SootopolisCity_EventScript_StartWalkToCaveOfOriginNorth
msgbox	STEVEN: Hör zu, PLAYER.Lässt dich der Anblick von GROUDON und KYOGRE glauben, dass man POKéMON fürchten muss?Aber das stimmt nicht. POKéMON sind eigentlich eher……Warum frage ich dich das überhaupt? Du weißt es doch bereits.
closemessage
applymovement LOCALID_SOOTOPOLIS_STEVEN SootopolisCity_Movement_StevenWalkToCaveOfOrigin
applymovement LOCALID_PLAYER SootopolisCity_Movement_PlayerWalkToCaveOfOrigin
waitmovement 0
delay 120
applymovement LOCALID_SOOTOPOLIS_EXPERT SootopolisCity_Movement_ExpertMoveAside
waitmovement 0
applymovement LOCALID_SOOTOPOLIS_STEVEN SootopolisCity_Movement_StevenArriveCaveEntrance
applymovement LOCALID_PLAYER SootopolisCity_Movement_PlayerArriveCaveEntrance
waitmovement 0
msgbox	STEVEN: Gut, da wären wir!Hier drinnen findest du jemanden namens WALLACE.Ich denke, du hast das Zeug, ihm zu helfen…
closemessage
setflag FLAG_STEVEN_GUIDES_TO_CAVE_OF_ORIGIN
applymovement LOCALID_PLAYER SootopolisCity_Movement_PlayerEnterCaveOfOrigin
waitmovement 0
warp CaveOfOrigin_Entrance 9 20
waitstate
end
= SootopolisCity_EventScript_StartWalkToCaveOfOriginNorth
applymovement LOCALID_SOOTOPOLIS_STEVEN SootopolisCity_Movement_StevenStartWalkToCaveOfOrigin
applymovement LOCALID_PLAYER SootopolisCity_Movement_PlayerStartWalkToCaveOfOriginNorth
waitmovement 0
return
= SootopolisCity_EventScript_StartWalkToCaveOfOriginWest
applymovement LOCALID_SOOTOPOLIS_STEVEN SootopolisCity_Movement_StevenStartWalkToCaveOfOrigin
applymovement LOCALID_PLAYER SootopolisCity_Movement_PlayerStartWalkToCaveOfOriginWest
waitmovement 0
return
