goto_if_ge VAR_SOOTOPOLIS_CITY_STATE 6 SootopolisCity_EventScript_KiriGiveBerry
goto_if_eq VAR_SOOTOPOLIS_CITY_STATE 5 SootopolisCity_EventScript_KiriRayquaza
